values
  ('seed:1', 'pending', '(E)-Stilbene', 'C(=C/c1ccccc1)\c1ccccc1', true, null, 'Aryl alkenes', 'acceptor', 'exp', 49, 1, '49 ± 1 kcal/mol', 'Spectroscopic (transoid, near-planar triplet)', 'Spectroscopic S0→T1 excitation energy, quoted as the best estimate. This text does not describe the original measurement; it is in the cited references (refs 1 and 2 of the paper).', 'Not given in the passage', 'Saltiel, Chang, Megarity, Rousseau, Shannon, Thomas, Uriarte, Pure Appl. Chem. 1975, 41, 559–579', null, 'pp. 560–561, section on the interaction of stilbene triplets with quenchers', 'spectroscopic triplet excitation energy is 49 ± 1 kcal/mol', 'The transoid triplet lies 49 ± 1 kcal/mol above ground-state trans-stilbene. trans-Stilbene behaves as a classical (vertical) acceptor. The twisted triplet is nearly isoenergetic with the transoid one.', 'https://joomla.iupac.org/publications/pac/1975/pdf/4104x0559.pdf', 'Free PDF (IUPAC)', null, null, null, 'primaria', 'Read in the journal''s free PDF. The paper that made the measurement still has to be retrieved.', null, null, 'literature'),
  ('seed:2', 'pending', '(Z)-Stilbene', 'C(=C\c1ccccc1)\c1ccccc1', false, null, 'Aryl alkenes', 'acceptor', 'exp', 57, null, '57 kcal/mol', 'Spectroscopic, vertical', 'Spectroscopic vertical excitation energy, quoted value. The original measurement is in the cited references (ref. 3, Hammond et al. 1964).', 'Not given in the passage', 'Saltiel, Chang, Megarity, Rousseau, Shannon, Thomas, Uriarte, Pure Appl. Chem. 1975, 41, 559–579', null, 'p. 560', null, '57 kcal/mol is the vertical energy of cis-stilbene. The cis isomer also accepts energy from donors with lower E_T, because the triplet is stabilised by twisting toward the perpendicular geometry (non-vertical transfer).', 'https://joomla.iupac.org/publications/pac/1975/pdf/4104x0559.pdf', 'Free PDF (IUPAC)', null, null, null, 'primaria', 'Read in the journal''s free PDF. The paper that made the measurement still has to be retrieved.', null, null, 'literature'),
  ('seed:3', 'pending', 'Styrene', 'C=Cc1ccccc1', false, null, 'Aryl alkenes', 'acceptor', 'exp', 62, null, '2.69 eV (0-0 transition)', 'Spectroscopic, 0-0 band', 'Low-energy electron-energy-loss spectroscopy (EELS), vibrationally resolved bands', 'Styrene film on solid argon, 15 K', 'Swiderek et al., J. Chem. Phys. 1994, 100, 70–77', null, 'Abstract', 'locate the 0-0 transition to the lowest triplet state at 2.69 eV', 'The same work places T2 with a 0-0 transition at 3.98 eV. The conversion to 62.0 kcal/mol is mine.', null, null, null, 'https://acnpsearch.tweb-dev.unibo.it/singlejournalindex/34369105', 'Index record with abstract', 'abstract', 'Only the abstract was read, from a bibliographic index. DOI and full text still to be retrieved.', null, null, 'literature'),
  ('seed:4', 'pending', '(E)-Anethole', 'C/C=C/c1ccc(OC)cc1', false, null, 'β-Alkylstyrenes', 'acceptor', 'calc', 58.1, null, '58.1 kcal/mol', 'Computed, 0-0 transition', 'DFT, B3LYP/6-31G*', 'Details (solvent model, ZPE) are in the Supplementary Materials, not read yet', 'Korff, Paulisch, Glorius, Doltsinis, Wünsch, Molecules 2022, 27, 5342', '10.3390/molecules27165342', 'Section 2 (Results), p. 4', 'density functional theory (DFT) using the B3LYP functional and the 6-31G* basis set', 'The authors compute E_T because they found no experimental value for anethole. With Ir(p-tBu-ppy)3 (54.5 kcal/mol) they reach E:Z 10:90.', 'https://mdpi-res.com/d_attachment/molecules/molecules-27-05342/article_deploy/molecules-27-05342.pdf', 'Open-access PDF (CC BY)', 'https://www.mdpi.com/article/10.3390/molecules27165342/s1', null, null, 'primaria', 'Read in the open-access PDF.', null, null, 'literature'),
  ('seed:5', 'pending', '(Z)-Anethole', 'C/C=C\c1ccc(OC)cc1', false, null, 'β-Alkylstyrenes', 'acceptor', 'calc', 60.8, null, '60.8 kcal/mol', 'Computed, 0-0 transition', 'DFT, B3LYP/6-31G*', 'Details (solvent model, ZPE) are in the Supplementary Materials, not read yet', 'Korff, Paulisch, Glorius, Doltsinis, Wünsch, Molecules 2022, 27, 5342', '10.3390/molecules27165342', 'Section 2 (Results), p. 4', 'density functional theory (DFT) using the B3LYP functional and the 6-31G* basis set', 'Computed together with the E isomer and 2.7 kcal/mol higher. With thioxanthone (63.3 kcal/mol) the E:Z ratio is 50:50.', 'https://mdpi-res.com/d_attachment/molecules/molecules-27-05342/article_deploy/molecules-27-05342.pdf', 'Open-access PDF (CC BY)', 'https://www.mdpi.com/article/10.3390/molecules27165342/s1', null, null, 'primaria', 'Read in the open-access PDF.', null, null, 'literature'),
  ('seed:6', 'pending', '1-Phenylcyclohexene', 'C1CCC(=CC1)c1ccccc1', false, null, 'Cyclic styrenes', 'acceptor', 'exp', 56, 3.4, '56 ± 3.4 kcal/mol', 'Relaxed triplet', 'Time-resolved photoacoustic calorimetry (PAC)', 'Methanol; the text says results in cyclohexane are almost identical', 'Goodman, Peters, Misawa, Caldwell, J. Am. Chem. Soc. 1986, 108, 6803–6805', null, 'p. 6805', null, 'The relaxed value sits just below the expected spectroscopic energy of 60 kcal/mol. The authors attribute this to partial relaxation, with less than 90° of rotation.', null, null, null, 'https://scite.ai/authors/john-d-carpenter-8nLXp9', 'Excerpt on a citation index', 'secondaria', 'Read in an excerpt reproduced by a citation index, with OCR errors, so no verbatim line is given. Numbers and page must be checked against the PDF.', null, null, 'literature'),
  ('seed:7', 'pending', '1,1-Bis(4-bromophenyl)ethene', 'C=C(c1ccc(Br)cc1)c1ccc(Br)cc1', false, null, '1,1-Diarylethenes', 'acceptor', 'exp', 51, 2.1, '51.0 ± 2.1 kcal/mol', 'Relaxed triplet', 'Time-resolved photoacoustic calorimetry (PAC)', 'Not given in the abstract', 'Arnaut, Caldwell, Elbert, Melton, Rev. Sci. Instrum. 1992, 63, 5381–5389', '10.1063/1.1143407', 'Abstract', 'a triplet energy of 51.0±2.1 kcal/mol have been measured for 1,1-bis-(p-bromophenyl)ethene', 'Transient lifetime 7.53 ± 0.2 ns, in agreement with kinetic absorption spectroscopy. The authors say the energy matches what is expected from unsubstituted 1,1-diphenylethene.', null, null, null, null, null, 'abstract', 'Only the abstract was read.', null, null, 'literature'),
  ('seed:8', 'pending', '2-Cyclopentenone', 'O=C1CCC=C1', false, 'This is an enone, not a styrene: you decide whether it belongs in this class.', 'Enones', 'acceptor', 'exp', 73.1, 1.1, '73.1 ± 1.1 kcal/mol', 'Relaxed triplet', 'Time-resolved photoacoustic calorimetry (PAC)', 'Not given in the abstract', 'Arnaut, Caldwell, Elbert, Melton, Rev. Sci. Instrum. 1992, 63, 5381–5389', '10.1063/1.1143407', 'Abstract', null, 'Presented as a transient for which interpretable PAC measurements were not possible before. The abstract gives the value with its uncertainty.', null, null, null, null, null, 'abstract', 'Only the abstract was read.', null, null, 'literature'),
  ('seed:9', 'pending', 'Alkenylboronate 4a (styryl-Bpin)', 'CC1(C)OB(/C=C/c2ccccc2)OC1(C)C', false, 'The structure of 4a is in Scheme 2, which I could not see: the SMILES is my assumption ((E)-styryl-Bpin).', 'Alkenylboronates', 'acceptor', 'calc', 52, null, '52 kcal/mol', 'Computed, electronic energy', 'DFT, ωB97XD/aug-cc-pVTZ, electronic energy', 'CH2Cl2 (solvent model)', 'Liu, Ni, Stevenson, Tripathy, Braley, Raghavachari, Swierk, Brown, Angew. Chem. Int. Ed. 2022, 61, e202200725', '10.1002/anie.202200725', 'Text on p. 2 and caption of Scheme 2', 'Calculated triplet energies, CH2Cl2, electronic energy, ωB97XD/aug-cc-pVTZ', 'Bpin lowers E_T relative to the other alkenes in the work (55–56 kcal/mol for 1–3). The authors warn that computed values come out lower than experimental ones and that the true value for 4a is probably above 52.', 'https://par.nsf.gov/servlets/purl/10341905', 'Accepted manuscript (NSF PAR)', null, null, null, 'primaria', 'Text read in the accepted manuscript on NSF PAR. The structure must be confirmed against the scheme.', null, null, 'literature')
